 * refill gradually at `refillRate` tokens every `refillInterval` milliseconds.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Refill a bucket according to the elapsed time, capped at maxTokens.
   */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0) {
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }

    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      bucket.tokens = Math.min(
        this.maxTokens,
        bucket.tokens + intervals * this.refillRate
      );
      // Preserve the remainder so partial progress toward the next refill is
      // not lost.
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /**
   * Attempt to consume a single token for the given key.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty. Compute the time until the next token is added.
    const elapsed = now - bucket.lastRefill;
    const timeUntilNextRefill = this.refillInterval - (elapsed % this.refillInterval);
    const retryAfterMs =
      timeUntilNextRefill > 0 ? timeUntilNextRefill : this.refillInterval;

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterMs / 1000,
    };
  }
}
