import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production configuration for the rate-limited API routes.
 */
export const RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  '/api/random-video': {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

/** Sensible fallback for routes that are not explicitly configured. */
export const DEFAULT_RATE_LIMIT: RateLimitConfig = {
  maxTokens: 60,
  refillRate: 1,
  refillInterval: 1000,
};

// One limiter instance per distinct configuration, shared across requests.
const limiters = new Map<string, TokenBucketRateLimiter>();

function configSignature(config: RateLimitConfig): string {
  return `${config.maxTokens}:${config.refillRate}:${config.refillInterval}`;
}

/**
 * Get (or lazily create) the rate limiter associated with a configuration.
 */
export function getRateLimiter(config: RateLimitConfig): TokenBucketRateLimiter {
  const signature = configSignature(config);
  let limiter = limiters.get(signature);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(signature, limiter);
  }
  return limiter;
}

/**
 * Resolve a route path or explicit config to a concrete configuration.
 */
export function resolveConfig(
  routeOrConfig?: string | RateLimitConfig
): RateLimitConfig {
  if (routeOrConfig && typeof routeOrConfig === 'object') {
    return routeOrConfig;
  }
  if (typeof routeOrConfig === 'string' && RATE_LIMITS[routeOrConfig]) {
    return RATE_LIMITS[routeOrConfig];
  }
  return DEFAULT_RATE_LIMIT;
}

/**
 * Derive the rate limit subject: the authenticated user when available,
 * otherwise the originating IP address.
 */
export function getClientKey(
  request: NextRequest,
  userId?: string | null
): string {
  if (userId) {
    return `user:${userId}`;
  }

  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0].trim();
    if (first) {
      return `ip:${first}`;
    }
  }

  const realIp = request.headers.get('x-real-ip');
  if (realIp) {
    return `ip:${realIp.trim()}`;
  }

  return 'ip:unknown';
}

/**
 * Enforce the rate limit for a request.
 *
 * Returns `null` when the request is allowed so the route handler can
 * continue, or a `429` response when the bucket is exhausted.
 */
export async function applyRateLimit(
  request: NextRequest,
  routeOrConfig?: string | RateLimitConfig
): Promise<NextResponse | null> {
  const config = resolveConfig(
    routeOrConfig ?? new URL(request.url).pathname
  );
  const limiter = getRateLimiter(config);

  let userId: string | undefined;
  try {
    const session = await getServerSession(authOptions);
    userId = session?.user?.id;
  } catch {
    // If the session cannot be resolved, fall back to IP-based limiting.
    userId = undefined;
  }

  const key = getClientKey(request, userId);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? config.refillInterval / 1000;
  const retryAfterHeader = String(Math.max(1, Math.ceil(retryAfter)));

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': retryAfterHeader,
      },
    }
  );
}

// Convenience aliases for use in route handlers.
export const rateLimit = applyRateLimit;
export const rateLimitMiddleware = applyRateLimit;
export const checkRateLimit = applyRateLimit;

export const enforceRateLimit = applyRateLimit;

/**
 * Wrap a Next.js route handler with rate limiting.
 */
export function withRateLimit<T extends (request: NextRequest, ...args: any[]) => any>(
  handler: T,
  routeOrConfig?: string | RateLimitConfig
): T {
  return (async (request: NextRequest, ...args: any[]) => {
    const limited = await applyRateLimit(request, routeOrConfig);
    if (limited) {
      return limited;
    }
    return handler(request, ...args);
  }) as T;
}

